// The last 14 scheduled nightly runs, newest first; each may have a nightly-summary.
const runs = $('Nightly runs').first().json.workflow_runs;
return (Array.isArray(runs) ? runs : []).slice(0, 14).map((r) => ({ json: { run_id: r.id } }));

// Runs from before Story 7.1 have no nightly-summary; they are skipped.
return $input.all()
  .map((i) => (i.json.artifacts ?? []).find((a) => a.name === 'nightly-summary' && !a.expired))
  .filter(Boolean)
  .map((a) => ({ json: { url: a.archive_download_url } }));

// S13, the daily QA update (EXPERIENCE.md M13). It always posts, even with
// no result, so a missing nightly is never silent.

// Words copied from contracts/vocabulary.json (test_status, triage_class and
// reactions). scripts/tests/test_n8n_workflows.py checks that the copy still matches.
const STATUS = { passed: 'PASSED', failed: 'FAILED', 'passed-on-retry': 'PASSED ON RETRY', quarantined: 'QUARANTINED' };
const CLASS = { product_defect: 'Product defect', test_defect: 'Test defect', environment: 'Environment', flaky: 'Flaky', unknown: 'Unknown' };
const REACTION = { bug: '🐞 Bug', flaky: '🔁 Flaky', environment: '🌩️ Environment', ignore: '🙈 Ignore' };
const MAX_LINES = 10;
const FLAKY_TARGET = 2; // percent (NFR-03)

const now = new Date();
const istParts = (date, options) => Object.fromEntries(
  new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Kolkata', ...options }).formatToParts(date).map((p) => [p.type, p.value]),
);
const today = istParts(now, { day: '2-digit', month: 'short' });
const shortDate = (ymd) => { const d = istParts(new Date(`${ymd}T12:00:00Z`), { day: '2-digit', month: 'short' }); return `${d.day} ${d.month}`; };
const shortName = (id) => id.split('::').pop().split(' > ').pop();
const cut = (lines) => lines.length > MAX_LINES
  ? [...lines.slice(0, MAX_LINES), `and ${lines.length - MAX_LINES} more — see the run`] : lines;

const summaries = $('Read summary').isExecuted
  ? $('Read summary').all().map((i) => i.json.data).filter((s) => s && s.nightly_run_id) : [];
const newestRun = ($('Nightly runs').first().json.workflow_runs ?? [])[0];
// Last night = the newest scheduled run, if it started in the last 36 hours and saved a summary.
const fresh = newestRun && now - new Date(newestRun.run_started_at ?? newestRun.created_at) < 36 * 3600000;
const last = fresh ? summaries.find((s) => s.nightly_run_id === newestRun.id) : undefined;

const lines = [];
const links = [];
if (!last) {
  lines.push('Nightly run: no result found for last night.');
} else {
  const c = last.counts;
  const where = `Nightly (${last.target || 'UAT'})`;  // "pretend site" on the prototype
  const head = last.status === 'not-run' ? `${where}: not run.` : `${where}: *${STATUS[last.status]}* — ${c.passed} passed, ${c.failed} failed, ${c.passed_on_retry} passed on retry.`;
  lines.push(head);
  const { automated, total } = last.coverage;
  lines.push(`Coverage: ${automated} of ${total} regression flows automated (${total ? Math.round((automated * 100) / total) : 0}%).`);
  links.push({ label: 'Nightly run', url: last.links.run });
  if (last.links.report) links.push({ label: 'Allure report', url: last.links.report });
}

// Flaky rate (NFR-03): tests that failed and then passed on retry, out of all tests that ran.
const nights = summaries.slice(0, 14);
if (nights.length) {
  const retried = nights.reduce((n, s) => n + s.counts.passed_on_retry, 0);
  const ran = nights.reduce((n, s) => n + s.counts.passed + s.counts.failed + s.counts.passed_on_retry + s.counts.quarantined, 0);
  const rate = ran ? (retried * 100) / ran : 0;
  const label = nights.length < 14 ? `last ${nights.length} night${nights.length === 1 ? '' : 's'}` : 'last 14 nights';
  let line = `Flaky rate (${label}): ${rate.toFixed(1)}%.`;
  if (rate > FLAKY_TARGET) line += ' Above the 2% target. Review flaky tests and react 🔁 Flaky to quarantine them.';
  lines.push(line);
}

// Last night's failure messages and their decisions (W3 and W3b). A failure
// with no Slack message (Slack off, or not posted yet) shows no class.
const read = $('Decisions').first().json;
const decisionsRead = read.decisions !== undefined;
const rows = !last || !decisionsRead ? []
  : (Array.isArray(read.decisions) ? read.decisions : JSON.parse(read.decisions || '[]'))
    .filter((r) => r.nightly_run_id === String(last.nightly_run_id));
const byTest = Object.fromEntries(rows.map((r) => [r.test_id, r]));
// Names as plain text, so the daily update doesn't notify people every morning.
const who = (r) => (r.actor_name ? `@${r.actor_name}` : `<@${r.actor_id}>`);
const oneLine = (text) => { const t = String(text).replace(/\s+/g, ' ').trim(); return t.length > 200 ? `${t.slice(0, 199)}…` : t; };
const decision = (r) => {
  if (!r?.action) return 'no decision yet';
  if (r.action === 'ignore') return `${REACTION.ignore} by ${who(r)}, waiting for a reason`;
  return [REACTION[r.action], r.jira_key, `by ${who(r)}`].filter(Boolean).join(' ');
};
const ignored = (r) => r?.action === 'ignore' && r.state === 'handled';

if (last) {
  const open = last.failures.filter((f) => f.status !== 'quarantined');
  const failures = open.filter((f) => !ignored(byTest[f.test_id])).map((f) => {
    const r = byTest[f.test_id];
    const parts = [`\`${shortName(f.test_id)}\``, STATUS[f.status]];
    if (r) parts.push(CLASS[r.class] ?? 'Not classified');
    return `• ${[...parts, decision(r)].join(' — ')}`;
  });
  const ignoredLines = open.filter((f) => ignored(byTest[f.test_id])).map((f) => {
    const r = byTest[f.test_id];
    return `• \`${shortName(f.test_id)}\` — ${REACTION.ignore} by ${who(r)}: "${oneLine(r.reason)}"`;
  });
  lines.push('');
  if (failures.length) {
    lines.push('*Failures and decisions*', ...cut(failures));
  } else if (!ignoredLines.length && last.status !== 'not-run') {
    lines.push('No failures last night.');
  }
  if (ignoredLines.length) lines.push('', '*Ignored (with reasons)*', ...cut(ignoredLines));
  if (open.length && !decisionsRead) lines.push('Decisions: not available (the audit database didn\'t answer).');
  const quarantined = last.quarantine.map((q) => `• \`${shortName(q.test_id)}\` — *QUARANTINED*, owner ${q.owner}, ${q.jira}, deadline ${shortDate(q.deadline)}`);
  if (quarantined.length) lines.push('', '*Quarantined*', ...cut(quarantined));
}

lines.push('', 'Datadog: not available.');
const switchValue = $('Read AGENT_ENABLED').first().json.value;
if (switchValue !== 'true') lines.push('AI work is off (`AGENT_ENABLED` is not `true`): failures are not classified.');

return [{
  json: {
    kind: '',
    header: `Daily QA update — ${today.day} ${today.month}, 09:30 IST`,
    body: lines.join('\n').replace(/\n{3,}/g, '\n\n'),
    todo: '',
    links,
    thread_ts: '',
    nightly_run_id: last?.nightly_run_id ?? null,
    ai_off: switchValue !== 'true',
  },
}];

// One audit entry per update. If Slack didn't take it, fail so W0 alerts.
const r = $input.first().json;
const u = $('Build update').first().json;
if (!r.posted && !r.preview) throw new Error(`Daily update not posted: ${r.error}`);
return [{
  json: {
    actor: 'n8n:w4-daily-update',
    actor_type: 'n8n',
    action: (r.posted ? 'daily-update-posted' : 'daily-update-preview') + (u.ai_off ? '-ai-off' : ''),
    target: u.nightly_run_id ? `nightly ${u.nightly_run_id}` : 'no nightly result',
    link: r.link || '',
  },
}];
